function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  const { compile } = require("tailwindcss");
  const c = await compile("@theme { --placeholder-color-brand: #123456; --background-color-brand: #abcdef; }\n@tailwind utilities;");
  const css = c.build(["placeholder-brand"]);
  if (!css.includes("::placeholder")) broken("no ::placeholder rule for placeholder-brand: " + css);
  if (css.includes("--background-color-brand") && !css.includes("--placeholder-color-brand")) symptom("placeholder-brand reads --background-color-brand instead of --placeholder-color-brand");
  if (!/color:\s*var\(--placeholder-color-brand\)/.test(css)) broken("unexpected output: " + css);
  console.log("OK: placeholder-brand uses --placeholder-color-brand");
})().catch(e => broken(String((e && e.stack) || e)));

